    if line.starts_with("\\!") || line.starts_with("\\#") {
        line = &line[1..];
        is_absolute = line.chars().nth(0) == Some('/');
    } else {
        if line.starts_with("!") {
            glob.is_whitelist = true;
            line = &line[1..];
